// Factory declarations below are generated by Andurel.

type ProjectFactory struct {
	models.ProjectEntity
}

type ProjectOption func(*ProjectFactory)

func BuildProject(opts ...ProjectOption) models.ProjectEntity {
	f := &ProjectFactory{
		ProjectEntity: models.ProjectEntity{
			Published:       randomBool(),
			Title:           faker.Word(),
			Slug:            faker.Word(),
			StartedAt:       sql.NullTime{Time: time.Now(), Valid: true},
			Status:          faker.Word(),
			Description:     faker.Word(),
			Content:         faker.Word(),
			ProjectUrl:      sql.NullString{String: faker.Word(), Valid: true},
			MetaTitle:       faker.Word(),
			MetaDescription: faker.Word(),
			ImageLink:       sql.NullString{String: faker.Word(), Valid: true},
			MetaImageLink:   sql.NullString{String: faker.Word(), Valid: true},
		},
	}

	for _, opt := range opts {
		opt(f)
	}

	return f.ProjectEntity
}

func CreateProject(
	ctx context.Context,
	exec storage.Executor,
	opts ...ProjectOption,
) (models.ProjectEntity, error) {
	built := BuildProject(opts...)

	entity := models.ProjectEntity{
		ID:              built.ID,
		CreatedAt:       time.Now(),
		UpdatedAt:       time.Now(),
		Published:       built.Published,
		Title:           built.Title,
		Slug:            built.Slug,
		StartedAt:       built.StartedAt,
		Status:          built.Status,
		Description:     built.Description,
		Content:         built.Content,
		ProjectUrl:      built.ProjectUrl,
		MetaTitle:       built.MetaTitle,
		MetaDescription: built.MetaDescription,
		ImageLink:       built.ImageLink,
		MetaImageLink:   built.MetaImageLink,
	}

	if err := exec.NewInsert().Model(&entity).Returning("*").Scan(ctx); err != nil {
		return models.ProjectEntity{}, err
	}

	return entity, nil
}

func CreateProjects(
	ctx context.Context,
	exec storage.Executor,
	count int,
	opts ...ProjectOption,
) ([]models.ProjectEntity, error) {
	projects := make([]models.ProjectEntity, 0, count)

	for i := range count {
		entity, err := CreateProject(ctx, exec, opts...)
		if err != nil {
			return nil, fmt.Errorf("failed to create project %d: %w", i+1, err)
		}
		projects = append(projects, entity)
	}

	return projects, nil
}

